import { View, Text, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "p1", name: "Чихэвч" }, { id: "p2", name: "Гар цаг" },
  { id: "p3", name: "Нарны шил" }, { id: "p4", name: "Цүнх" },
  { id: "p5", name: "Ном" }, { id: "p6", name: "Гутал" },
  { id: "p7", name: "Аяга" }, { id: "p8", name: "Бэлгийн карт" },
];
const fakeApi = () => new Promise((res) => setTimeout(() => res(PRODUCTS), 200));

function App() {
  const [count, setCount] = useState(0);
  useEffect(() => {
    let alive = true;
    fakeApi().then((data) => { if (alive) setCount(data.length); });
    return () => { alive = false; };
  }, []);
  return (
    <View style={styles.s}>
      <Text nativeID="count" style={styles.c}>Нийт бараа: {count}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, alignItems: "center", justifyContent: "center", padding: 24 },
  c: { fontSize: 22, fontWeight: "bold", color: "#0f172a" },
});

registerRootComponent(App);
